shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('test/xchar-test.cc')
s = path.read_text()
needle = 'TEST(locale_test, format) {\n'
assert s.count(needle) == 1
s = s.replace(needle, '''TEST(locale_test, localized_float_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<char>());
  EXPECT_EQ("           -119?921", fmt::format(loc, "{:19.3Lf}", -119.921));
  EXPECT_EQ("          2~194?139", fmt::format(loc, "{:19.3Lf}", 2194.139));
  EXPECT_EQ("            -57?639", fmt::format(loc, "{:19.3Lf}", -57.639));
  EXPECT_EQ("             -5?980", fmt::format(loc, "{:19.3Lf}", -5.980));
  EXPECT_EQ("             -2?119", fmt::format(loc, "{:19.3Lf}", -2.119));
  EXPECT_EQ("              0?295", fmt::format(loc, "{:19.3Lf}", 0.295));
  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295));
  EXPECT_EQ("              1?000", fmt::format(loc, "{:19.3Lf}", 0.9996));
  EXPECT_EQ("      1~234~567?890", fmt::format(loc, "{:19.3Lf}", 1234567.89));
  EXPECT_EQ("    1?234567", fmt::format(loc, "{:12L}", 1.234567));
  EXPECT_EQ("1?295*****", fmt::format(loc, "{:*<10.3Lf}", 1.295));
  EXPECT_EQ("**1?295***", fmt::format(loc, "{:*^10.3Lf}", 1.295));
  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295L));

  auto small_loc = std::locale(std::locale(), new small_grouping<char>());
  EXPECT_EQ("       1,2.345", fmt::format(small_loc, "{:14.3Lf}", 12.345));
}

TEST(locale_test, localized_wfloat_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
  EXPECT_EQ(L"              0?295", fmt::format(loc, L"{:19.3Lf}", 0.295));
  EXPECT_EQ(L"              1?295", fmt::format(loc, L"{:19.3Lf}", 1.295));
  EXPECT_EQ(L"          2~194?139", fmt::format(loc, L"{:19.3Lf}", 2194.139));
  EXPECT_EQ(L"1?295*****", fmt::format(loc, L"{:*<10.3Lf}", 1.295));
  EXPECT_EQ(L"**1?295***", fmt::format(loc, L"{:*^10.3Lf}", 1.295));
}

''' + needle)
path.write_text(s)
PY
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized*float_alignment'

